return {["dianshitimu"]={["1"]={["ambit"]=0.4,["art"]=1,["id"]=1,["innovate"]=0.1,["practical"]=0.3,["question"]=[[今日天气晴好，梅花初绽，就以梅花为题，畅所欲言吧。]],["truth"]=0.2},["2"]={["ambit"]=0.5,["art"]=0.2,["id"]=2,["innovate"]=0.1,["practical"]=0.9,["question"]=[[今日收到塘报，北狄入寇，朕甚忧，就以保家卫国为题，畅所欲言吧。]],["truth"]=0.3},["3"]={["ambit"]=0.3,["art"]=0.2,["id"]=3,["innovate"]=0.1,["practical"]=1,["question"]=[[前几日户部尚书告诉朕，近年来财政支出颇大，国库日蹇。今日就以开源节流为题，写些文章吧。]],["truth"]=0.4},["4"]={["ambit"]=0.2,["art"]=0.4,["id"]=4,["innovate"]=0.1,["practical"]=1,["question"]=[[昨日海外藩国遣使给朕送了柄宝剑，端的是锋利无比。今日就百工以为题，写些文章吧。]],["truth"]=0.3},["5"]={["ambit"]=1,["art"]=0.2,["id"]=5,["innovate"]=0.1,["practical"]=0.5,["question"]=[[前日朕得了一张四海堪舆图，乃知天下之大。今日就以格物致知为题，写些文章吧。]],["truth"]=0.2},["6"]={["ambit"]=1,["art"]=0.2,["id"]=6,["innovate"]=0.1,["practical"]=0.5,["question"]=[[前日朕摘了一些人的官帽、下令查处了一批贪官污吏。今日就以廉洁奉公为题，写些文章吧。]],["truth"]=0.2},["7"]={["ambit"]=0.5,["art"]=0.2,["id"]=7,["innovate"]=0.1,["practical"]=0.2,["question"]=[[前日有人给朕进贡了一批祥瑞，朕甚欣喜。今日就以吉凶为题，畅所欲言吧。]],["truth"]=1},["8"]={["ambit"]=0.2,["art"]=0.2,["id"]=8,["innovate"]=0.1,["practical"]=0.5,["question"]=[[前几钦天监向朕进献了新的历法。朕甚欣喜。今日就以时节为题，写些文章吧。]],["truth"]=1}},["shengshi"]={["1"]={["answer"]=[[YEL意诚而后心正]],["book"]=[[daxue]],["bookName"]=[[大学]],["id"]=1,["question"]=[[知至而后意诚，_________，心正而后身修，身修而后家齐，家齐而后国治，国治而后天下平。 ]]},["10"]={["answer"]=[[YEL不可须臾离也]],["book"]=[[zhongyong]],["bookName"]=[[中庸]],["id"]=10,["question"]=[[道也者，_________；可离，非道也。是故君子戒慎乎其所不睹，恐惧乎其所不闻。 ]]},["11"]={["answer"]=[[YEL中庸不可能也]],["book"]=[[zhongyong]],["bookName"]=[[中庸]],["id"]=11,["question"]=[[天下国家，可均也；爵禄，可辞也；白刃，可蹈也；_________。]]},["12"]={["answer"]=[[YEL虽圣人亦有所不知焉]],["book"]=[[zhongyong]],["bookName"]=[[中庸]],["id"]=12,["question"]=[[夫妇之愚，可以与知焉，及其至也，______________。 ]]},["13"]={["answer"]=[[YEL亦勿施于人]],["book"]=[[zhongyong]],["bookName"]=[[中庸]],["id"]=13,["question"]=[[忠恕违道不远。施诸己而不愿，_______。]]},["14"]={["answer"]=[[YEL道并行而不相悖]],["book"]=[[zhongyong]],["bookName"]=[[中庸]],["id"]=14,["question"]=[[万物并育而不相害。_