]],["book"]=[[shijing]],["bookName"]=[[诗经]],["id"]=28,["question"]=[[七月在野，八月在宇，九月在户，______________。  ]]},["29"]={["answer"]=[[YEL在城阙兮]],["book"]=[[shijing]],["bookName"]=[[诗经]],["id"]=29,["question"]=[[青青子佩，悠悠我思。纵我不往，子宁不来？挑兮达兮，_________。一日不见，如三月兮。]]},["3"]={["answer"]=[[YEL言欲致吾之知]],["book"]=[[daxue]],["bookName"]=[[大学]],["id"]=3,["question"]=[[所谓致知在格物者，________，在其物而穷其理也。]]},["30"]={["answer"]=[[YEL非礼不决]],["book"]=[[liji]],["bookName"]=[[礼记]],["id"]=30,["question"]=[[道德仁义，非礼不成，教训正俗，非礼不备。分争辨讼，__________。]]},["31"]={["answer"]=[[YEL冠衣不纯素]],["book"]=[[liji]],["bookName"]=[[礼记]],["id"]=31,["question"]=[[为人子者：父母存，_________。孤子当室，冠衣不纯采。]]},["32"]={["answer"]=[[YEL国君则平衡]],["book"]=[[liji]],["bookName"]=[[礼记]],["id"]=32,["question"]=[[执天子之器则上衡，_________，大夫则绥之，士则提之。]]},["33"]={["answer"]=[[YEL必先行乡饮酒之礼]],["book"]=[[liji]],["bookName"]=[[礼记]],["id"]=33,["question"]=[[古者诸侯之射也，必先行燕礼；卿、大夫、士之射也，__________。]]},["34"]={["answer"]=[[YEL参之以三光]],["book"]=[[liji]],["bookName"]=[[礼记]],["id"]=34,["question"]=[[古之制礼也，经之以天地，纪之以日月，___________，政教之本也。]]},["35"]={["answer"]=[[YEL君子征凶]],["book"]=[[zhouyi]],["bookName"]=[[周易]],["id"]=35,["question"]=[[上九，既雨既处，尚德载。妇贞厉。月几望，________。]]},["36"]={["answer"]=[[YEL利涉大川]],["book"]=[[zhouyi]],["bookName"]=[[周易]],["id"]=36,["question"]=[[《蛊》：元亨。_______，先甲三日，后甲三日。]]},["37"]={["answer"]=[[YEL以其国君凶]],["book"]=[[zhouyi]],["bookName"]=[[周易]],["id"]=37,["question"]=[[用行师，终有大败，__________，至于十年不克征。]]},["38"]={["answer"]=[[YEL见恶人无咎]],["book"]=[[zhouyi]],["bookName"]=[[周易]],["id"]=38,["question"]=[[初九，悔亡。丧马勿逐自复。_______。]]},["39"]={["answer"]=[[YEL百姓昭明]],["book"]=[[shangshu]],["bookName"]=[[尚书]],["id"]=39,["question"]=[[克明俊德，以亲九族。九族既睦，平章百姓。________，协和万邦。]]},["4"]={["answer"]=[[YEL恶而知其美者]],["book"]=[[daxue]],["bookName"]=[[大学]],["id"]=4,["question"]=[[故好而知其恶,_________，天下鲜矣。 ]]},["40"]={["answer"]=[[YEL百姓如丧考妣]],["book"]=[[shangshu]],["bookName"]=[[尚书]],["id"]=40,["question"]=[[二十有八载，帝乃殂落。__________，三载，四海遏密八音。]]},["41"]={["answer"]=[[YEL时乃天道]],["book"]=[[shangshu]],["bookN